package com.vibecode.guide.application; import com.vibecode.roadmap.application.*; import com.vibecode.task.domain.WorkflowTaskStatus; import java.util.*; import org.springframework.stereotype.Service;
@Service public class DeterministicProjectGuide {private final ProjectStateService state;private final DeterministicNextStepEngine next;public DeterministicProjectGuide(ProjectStateService s,DeterministicNextStepEngine n){state=s;next=n;} public Map<String,Object> guide(UUID projectId){ProjectState s=state.state(projectId);WorkflowRecommendation r=next.recommend(projectId);return Map.of("whereYouAre",(s.currentPhase()==null?"Sem fase":s.currentPhase().title())+(s.currentTask()==null?"":", tarefa "+s.currentTask().title()),"whatWasCompleted",s.completedTasks(),"activeProblems",s.blockedTasks(),"recommendedNextStep",r,"reason",r.reason());}}
